"use strict";(globalThis.webpackChunkgrc||=[]).push([[13598],{69447(e){e.exports=JSON.parse('{"citeKey":"bateman2022luxio","slug":"bateman-2022-luxio-2487","title":"LuxIO: Intelligent Resource Provisioning and Auto-Configuration for Storage Services","authors":["K. Bateman","N. Rajesh","J. Cernuda","L. Logan","J. Ye","S. Herbein","A. Kougkas","X.-H. Sun"],"venue":"The 29th edition of the IEEE International Conference on High Performance Computing, Data, and Analytics (HiPC\'22)","type":"Conference","entryType":"inproceedings","date":"December, 2022","year":2022,"era":"iit","month":12,"doi":"10.1109/hipc56025.2022.00041","abstract":"Abstract-Storage in HPC is typically a single Remote and Static Storage (RSS) resource. However, applications demonstrate diverse I/O requirements that can be better served by a multi-storage approach. Cur- rent practice employs ephemeral storage systems running on either node- local or shared storage resources. Yet, the burden of provisioning and configuring intermediate storage falls solely on the users, while global job schedulers offer little to no support for custom deployments. This lack of support often leads to over- or under-provisioning of resources and poorly configured storage systems. To mitigate this, we present LuxIO, an intelli- gent storage resource provisioning and auto-configuration service. LuxIO constructs storage deployments configured to best match I/O require- ments. LuxIO-tuned storage services show performance improvements up to 2x across common applications and benchmarks, while introducing minimal overhead of 93.40 ms on top of existing job scheduling pipelines. LuxIO improves resource utilization by up to 25% in select workflows.","hasAbstract":true,"lede":"To mitigate this, we present LuxIO, an intelli- gent storage resource provisioning and auto-configuration service.","links":{"pdf":"https://grc.iit.edu/papers/2022/bateman-2022-luxio-2487.pdf"},"tags":["Resource Provisioning","I/O Behavior","Storage Auto-Tuning","ChronoLog"],"_projectIds":["chronolog","hermes","iris"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["dtio","chronolog","hermes","iris"],"memberAuthors":["bateman-keith","rajesh-neeraj","cernuda-jaime","logan-luke","ye-jie","kougkas-anthony","sun-xian-he"],"funding":[{"agency":"NSF","award":"OAC-1835764","projectId":"hermes"},{"agency":"NSF","award":"CSR-1814872","projectId":"iris"},{"agency":"NSF","award":"OAC-2104013","projectId":"chronolog"},{"agency":"ANL","award":"DE-AC02-06CH11357"}]}')}}]);